Below are Node.js examples and a recommended resend workflow tailored to X-Signature using HMAC-SHA256. These examples show secure signature verification (constant-time compare) and a safe resend approach. Replace placeholders (like process.env.WEBHOOK_SECRET, delivery IDs, and API endpoints) with your values.

A. Signature validation — Express middleware (HMAC-SHA256, header X-Signature)
- Key points implemented:
  - Uses raw request body bytes (important for HMAC correctness).
  - Computes HMAC-SHA256, hex-encodes the result.
  - Uses a constant-time comparison (crypto.timingSafeEqual).
  - Optional timestamp check shown if your provider includes a timestamp header.

Code (Express):
const crypto = require('crypto');
const express = require('express');
const app = express();

// Use a raw body parser for the webhook route so we get exact bytes
app.use('/webhook', express.raw({ type: '*/*' }));

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // new secret

function verifySignature(req) {
  const sigHeader = req.get('X-Signature');
  if (!sigHeader) return false;

  const rawBody = req.body; // Buffer from express.raw
  // Compute HMAC-SHA256 over raw bytes, hex encoded
  const hmac = crypto.createHmac('sha256', WEBHOOK_SECRET);
  hmac.update(rawBody);
  const computed = Buffer.from(hmac.digest('hex'), 'utf8');

  const received = Buffer.from(sigHeader, 'utf8');

  // Length check to avoid exceptions in timingSafeEqual
  if (received.length !== computed.length) {
    // still perform a timing-safe comparison with a same-length buffer to avoid leaking length info
    const fake = Buffer.alloc(computed.length);
    return crypto.timingSafeEqual(computed, fake) && false;
  }

  return crypto.timingSafeEqual(computed, received);
}

app.post('/webhook', (req, res) => {
  try {
    if (!verifySignature(req)) {
      // Log failure to internal logs (do not include raw payload or secrets)
      console.warn('Webhook signature verification failed for request from', req.ip);
      return res.status(401).send('Invalid signature');
    }

    // Parse JSON after verification (safe since we've consumed raw body)
    const payload = JSON.parse(req.body.toString('utf8'));

    // Process the payload...
    // Ensure idempotency by using payload.id or event id to dedupe

    res.sendStatus(200);
  } catch (err) {
    console.error('Error processing webhook:', err);
    res.sendStatus(500);
  }
});

app.listen(3000, () => console.log('Webhook listener running on port 3000'));

Notes:
- We defer parsing JSON until after signature verification to avoid any transformations.
- If your provider sends signature in hex vs base64, ensure header encoding matches. The example assumes hex-encoded signature (common for HMAC-SHA256).
- If signature header includes a prefix (e.g., "sha256=..."), strip the prefix before comparing.

If your provider sends a timestamp (e.g., X-Signature-Timestamp) and signs timestamp + "." + body:
Modify verifySignature to:
- Read timestamp header (e.g., const ts = req.get('X-Signature-Timestamp')).
- Build message = `${ts}.${rawBody.toString('utf8')}` (or as provider specifies).
- Compute HMAC over message bytes.
- Verify timestamp is within allowed window (e.g., Math.abs(Date.now()/1000 - Number(ts)) < 300).

