  // Replace with actual API that lists failed/pending webhook deliveries
  const res = await axios.get(`${API_BASE}/deliveries?status=failed`, {
    headers: { Authorization: `Bearer ${ADMIN_API_KEY}` },
  });
  return res.data.deliveries; // assume array
