    // which will sign the payload correctly with the active secret.
    const res = await axios.post(`${API_BASE}/deliveries/${delivery.id}/resend`, null, {
      headers: { Authorization: `Bearer ${ADMIN_API_KEY}` },
      timeout: 10000,
